"""Render the evidence register without converting unknown perceptual attributes to PASS."""
from pathlib import Path
import json,csv,collections
ROOT=Path(__file__).resolve().parents[2];P=ROOT/'docs/video-quality-audit-35.json'
def stamp(t):return f'{int(t)//60:02}:{t%60:05.2f}'
def main():
 d=json.loads(P.read_text());rows=d['records'];assert len(rows)==35
 summary=dict(expected_placements=35,source_assets_missing=sum(len(r['missing_assets']) for r in rows),duplicate_core_placements=35-len({r['mp4'] for r in rows}),inventory_and_source_audits=35,decoded_full_soundtrack_records=sum('decoded_frames' in r['verification_evidence'] for r in rows),passing_without_changes=sum(r['final_status']=='PASS' and not r['defects'] for r in rows),brand_text_corrections_required=sum(bool(r['attributes']['spoken_branding'].get('evidence')) for r in rows),unapproved_british_configurations=sum(r['voice_profile_check']=='FAIL_CONFIG' for r in rows),owner_reported_british_accent=5,animation_or_sync_review_flags=sum(bool(r['verification_evidence'].get('extended_static_intervals')) for r in rows),confirmed_animation_or_sync_corrections=sum(any(x['code']=='MISSING_NARRATED_VISUAL_MODEL' for x in r['defects']) for r in rows),blocked_by_unavailable_baseline_voice=0,baseline_voice_available=True,verified_enhanced_enthusiasm_voice_available=False,enhanced_voice_and_perceptual_release_blocked=35,phone_sized_chromium_playback=sum(bool(r['verification_evidence'].get('phone_playback',{}).get('advancing_playback')) for r in rows),brandfree_measurement_review_candidates_prepared=5,brandfree_review_candidates_prepared=d.get('brandfree_review_candidates_prepared',5),fully_perceptually_audited=0,fully_passing=sum(r['final_status']=='PASS' for r in rows),remediated_and_deployed=0)
 d['summary']=summary;P.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
 h=['# Mandatory 35-video quality audit and remediation','','**Production hold: active. No new topic, narration batch or video release is authorised by a technical PASS.**','', 'Baseline: `d31afb5dfae6f87564e0aaddc24c7ccb0af4acf3`. Exactly 35 core lesson placements across seven topics. The existing LCM extension is outside this 35-video scope and is listed separately; archived media are not duplicate core placements. No missing source assets were found.','', '## Evidence boundary','','Every record identifies the actual MP4, lesson placement, source script, captions, transcript, voice configuration, renderer and source audio. Downloaded published bytes, complete soundtrack ASR, all-frame decode/contrast/motion measurements, scene-frame OCR and beginning/middle/ending contact sheets are automated evidence, **not full perceptual listening/viewing**. No tool available in this session can certify heard accent, enthusiasm, naturalness or the complete teaching experience. Negative keyword/OCR matches cannot certify the absence of spoken/on-screen branding. Owner reports establish the five Measurement videos as the satisfactory audio baseline, not approval of the new enthusiasm requirement or all 35 mandatory attributes.','', 'No video receives PASS while a required attribute remains unexamined. `final_status=FAIL` denotes a confirmed textual/voice-profile defect; unknown attributes remain UNVERIFIED. `release_status=BLOCKED_PERCEPTUAL_REVIEW` is separate. A British configuration is not represented as a fresh listening observation; the owner specifically reports the five Multiplication videos as British.','', '## Counts at this checkpoint','']
 for k,v in summary.items():h.append(f'- {k.replace("_"," ")}: {v if v is not None else "UNVERIFIED — flags require concept-level review"}')
