 h+=['','## Per-video defect and verification register','']
 for r in rows:
  n=r['number'];ev=r['verification_evidence'];h +=[f"### {n:02}. {r['topic']} — {r['lesson']}",'',f"- Placement: [{r['page']}#{r['lesson_section']}](../{r['page']}#{r['lesson_section']}); [published MP4]({r['published_url']}).",f"- Voice: `{r['voice'].get('model')}` / `{r['voice'].get('name')}` / speaker `{r['voice'].get('speaker_id')}`. Configuration: **{r['voice_profile_check']}**; actual accent/enthusiasm review remains separate.",f"- Producer: [{r['producer']}](../{r['producer']}); graphics: [{r['graphics_source']}](../{r['graphics_source']}).",f"- Script: [{r['script']}](../{r['script']}) (`{r['script_key']}`); [timing](../{r['timing']}); [captions](../{r['captions']}); [transcript](../{r['transcript']}); [source audio](../{r['source_audio']}).",f"- Expected SHA-256: `{r['expected_sha256']}`; bytes: {r['expected_bytes']}."]
  if ev.get('full_audio_asr'):h +=[f"- Actual-media evidence: [technical measurements](video-quality-evidence/{n:02}/technical.json), [complete soundtrack ASR](video-quality-evidence/{n:02}/full-audio-asr.json), [all scene samples](video-quality-evidence/{n:02}/scene-contact.jpg), [beginning/middle/ending](video-quality-evidence/{n:02}/begin-middle-ending.jpg), [sampled-frame OCR](video-quality-evidence/{n:02}/sampled-frame-ocr.json).",f"- Decoded frames: {ev['decoded_frames']}; RMS: {ev['audio_rms']:.4f}; clipping fraction: {ev['clipping_fraction']:.6f}; long silence flags: {len(ev['long_silent_gaps'])}; static flags: {len(ev['extended_static_intervals'])}. Flags are not automatic perceptual failures."]
  review=r.get('review_replacement')
  if review:h.append(f"- Branding-edit review copy: [{Path(review['mp4']).name}](../{review['mp4']}); SHA-256 `{review['sha256']}`. Original voice preserved; **UNVERIFIED / NOT DEPLOYED**.")
  if r.get('visual_correction_preview'):h.append(f"- Missing-model animated scene preview: [MP4](../{r['visual_correction_preview']['preview']}); original audio, low-resolution draft only, not integrated into a full replacement.")
  h+=['','Specific confirmed defects / timestamps:','']
  for defect in r['defects']:h.append(f"- **{defect['code']}**, {stamp(defect['start'])}–{stamp(defect['end'])}: {defect['detail'].strip().replace(chr(10),' ')[:650]}")
  if not r['defects']:h.append('- No confirmed defect yet; mandatory attributes remain UNVERIFIED.')
  if ev.get('long_silent_gaps'):h.append('- Silence review intervals: '+', '.join(stamp(x['start'])+'–'+stamp(x['end']) for x in ev['long_silent_gaps'])+'.')
  if ev.get('extended_static_intervals'):h.append('- Static-scene review intervals: '+', '.join(stamp(x['start'])+'–'+stamp(x['end']) for x in ev['extended_static_intervals'])+'. Preserve appropriate persistent working; do not blindly animate every static interval.')
  h+=['','| Required attribute | Status | Evidence / remaining examination |','|---|---|---|']
  for key,a in r['attributes'].items():
   detail=a.get('evidence','See machine-readable register and linked actual-media evidence.');detail=detail if isinstance(detail,str) else 'Timestamped evidence recorded above / in JSON.';h.append(f"| {key.replace('_',' ')} | {a['status']} | {detail.replace('|','/')} |")
  h+=['', '**Required correction:** '+('; '.join(r['required_correction']))+'.', '', '**Release:** '+r['final_status']+' / '+r['release_status']+'. No full-video perceptual PASS claimed.','']
 file_inventory=d.get('repository_file_inventory',{})
 h+=['## Repository files outside the 35 core placements','', 'Existing archived MP4s are preserved, not counted as current core placements. Unclassified/unreferenced old files are flagged for archive review, not deleted or silently approved.','']
 for name in file_inventory.get('unclassified_unreferenced_mp4s_preserved',[]):h.append('- `'+name+'`')
 h+=['','## Controlled remediation and blockers','','1. Complete the 35-record evidence pass before preparing any replacement.','2. Prioritise removing branded endings from the five owner-approved Measurement narrations. Use packet-preserving cuts only at verified natural phrase boundaries, with candidate captions/transcripts and rollback manifests; never overwrite the live MP4.','3. Thirty branding-edited review copies are preserved: 29 exact H.264/AAC packet-prefix cuts and one internal Fractions edit preserving the optional LCM notice (215.7 seconds of original video packets, only a 7.6-second tail re-encoded; AAC re-encoded without pitch/speed changes). No corrected MP4 was deployed. Two original-audio animated scene previews correct the missing models, but are not full integrated replacements. Twenty videos have the wrong declared British voice profile, including all five owner-reported Multiplication videos. The approved baseline hf_alpha model is installed; do not substitute another accent. A verified **more expressive** setting and full listening/viewing remain unavailable, so do not waste compute regenerating a 20-video batch under an unverified setting.','4. ASR/OCR/pitch/static metrics cannot satisfy perceptual review. Release candidates remain blocked until an actual reviewer examines the exact candidate bytes against every mandatory attribute.','5. The single production contract is [video-agent/video-production-contract.json](../video-agent/video-production-contract.json); the default production hold and 16 guarded generation/integration entries prevent accidental restarts. Existing scheduled production remains disabled.','6. No quiz, authentication, Firebase, dashboard or unrelated site functionality is changed by this audit.','', '## Extra placement','','- Existing approved LCM extension: `videos/MathMagic_Finding_LCM_FINAL_1080p.mp4` within Fractions. Not counted among the 35 core placements, not deleted or modified.','']
 (ROOT/'docs/video-quality-audit-35.md').write_text('\n'.join(h).rstrip()+'\n')
